import{_ as t,o as a,c as d,a0 as s}from"./chunks/framework.K3sFe4KB.js";const u=JSON.parse('{"title":"Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"explanation/architecture.md","filePath":"explanation/architecture.md"}'),r={name:"explanation/architecture.md"};function o(n,e,i,c,l,p){return a(),d("div",null,[...e[0]||(e[0]=[s(`<h1 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h1><p>cicada is a Rust workspace built on ports-and-adapters (DDD). The point of the split: the same reconciliation engine powers the CLI a human runs and the MCP server an agent drives — with zero business-logic duplication.</p><h2 id="layers" tabindex="-1">Layers <a class="header-anchor" href="#layers" aria-label="Permalink to &quot;Layers&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Interfaces (CLI / MCP)        thin adapters, no business logic</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>Application (use cases)       Validate · Plan · Apply · Refresh ·</span></span>
<span class="line"><span>        │                     Drift · QueryRange · Show · Fmt</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>Domain (entities + services)  Calendar · Event · Recurrence ·</span></span>
<span class="line"><span>        │                     Attendee · Reminder · Time ·</span></span>
<span class="line"><span>        │                     EventDiffer · RecurrenceExpander ·</span></span>
<span class="line"><span>        │                     CapabilityChecker</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>Ports (traits)                CalendarProvider · StateStore ·</span></span>
<span class="line"><span>                              AuthProvider · Clock · Logger ·</span></span>
<span class="line"><span>                              SecretStore · Http</span></span></code></pre></div><p><code>cicada-core</code> holds domain, application, and ports — and is <strong>pure</strong>: no <code>std::fs</code>, no <code>tokio</code>, no HTTP types, no provider SDKs. Purity is what makes &quot;reuse across CLI and MCP&quot; real rather than aspirational: every side effect crosses a port trait, so the whole domain is testable with in-memory fakes — fast, deterministic, no network.</p><h2 id="the-seven-ports" tabindex="-1">The seven ports <a class="header-anchor" href="#the-seven-ports" aria-label="Permalink to &quot;The seven ports&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Port</th><th>Responsibility</th><th>Shipped adapter</th><th>Possible adapters</th></tr></thead><tbody><tr><td><code>CalendarProvider</code></td><td>list/get/create/update/delete events, <code>findByTag</code>, <code>freeBusy</code>, capabilities</td><td><code>cicada-google</code> (+ <code>FakeFileProvider</code> for tests)</td><td>Teams, CalDAV</td></tr><tr><td><code>StateStore</code></td><td>recorded state + apply journal</td><td><code>cicada-state</code> (versioned YAML on disk, locked, atomic)</td><td>GCS, S3 backends</td></tr><tr><td><code>AuthProvider</code></td><td>credential acquisition</td><td>Google OAuth / service-account / static token</td><td>per-provider auth</td></tr><tr><td><code>Clock</code></td><td>injectable <code>now()</code></td><td>system clock</td><td>fake clock (tests, golden plans)</td></tr><tr><td><code>Logger</code></td><td>structured logging</td><td>console</td><td><code>tracing</code> subscribers</td></tr><tr><td><code>SecretStore</code></td><td>token persistence</td><td>file store, <code>0600</code></td><td>OS keychain</td></tr><tr><td><code>Http</code></td><td>injectable fetch</td><td><code>reqwest</code> + retry wrapper</td><td>recorded-fixture client</td></tr></tbody></table><p><code>ProviderCapabilities</code> is first-class on <code>CalendarProvider</code>: attendee limits, reminder kinds, recurrence edge cases, conferencing kinds, notification suppression, tagging, conditional writes. The planner consults capabilities at plan time and rejects or warns on unsupported desired states — this is what makes multi-provider work honestly instead of silently dropping fields.</p><h2 id="why-a-pure-core" tabindex="-1">Why a pure core <a class="header-anchor" href="#why-a-pure-core" aria-label="Permalink to &quot;Why a pure core&quot;">​</a></h2><ul><li><strong>Two interfaces, one engine.</strong> <code>cicada</code> and <code>cicada-mcp</code> are thin shells that wire adapters into the same use cases. Agents get the identical lifecycle humans get — <code>plan.apply</code> calls the same <code>ApplyPlan</code> the <code>apply</code> verb calls.</li><li><strong>Testability.</strong> Domain and planning logic run against in-memory fakes; the Google adapter is exercised by recorded HTTP fixtures. The full lifecycle shipped and passed end-to-end tests before any Google code existed.</li><li><strong>Extensibility.</strong> New providers, state backends, auth methods, and interfaces are new adapters. The core never changes.</li></ul><h2 id="crates" tabindex="-1">Crates <a class="header-anchor" href="#crates" aria-label="Permalink to &quot;Crates&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Crate</th><th>Role</th></tr></thead><tbody><tr><td><code>cicada-core</code></td><td>domain + application + ports (the reusable gem)</td></tr><tr><td><code>cicada-schema</code></td><td>serde schema + YAML DSL parser → domain</td></tr><tr><td><code>cicada-state</code></td><td><code>JsonFileStateStore</code> — recorded state + journal</td></tr><tr><td><code>cicada-google</code></td><td><code>CalendarProvider</code> + <code>AuthProvider</code> impls (Calendar API + Meet)</td></tr><tr><td><code>cicada-shell</code></td><td>shared interface plumbing: provider wiring, file resolution, time-bound parsing</td></tr><tr><td><code>cicada-mcp</code></td><td><code>cicada-mcp</code> binary — MCP stdio server, transport only</td></tr><tr><td><code>cicada-cli</code></td><td><code>cicada</code> binary — verbs wire adapters into use cases</td></tr><tr><td><code>cicada-testkit</code></td><td>fakes, conformance suites, golden fixtures</td></tr></tbody></table><h2 id="single-write-path" tabindex="-1">Single write path <a class="header-anchor" href="#single-write-path" aria-label="Permalink to &quot;Single write path&quot;">​</a></h2><p>All mutations flow through plan/apply on declared YAML — the CLI has no <code>cicada event create</code> and MCP has no <code>events.create</code>. Two write paths would create unmanaged events that immediately surface as drift; one lifecycle keeps the world consistent.</p><h2 id="time-model" tabindex="-1">Time model <a class="header-anchor" href="#time-model" aria-label="Permalink to &quot;Time model&quot;">​</a></h2><p>Recurring events are stored as <code>(local wall time, IANA zone)</code> and materialised to instants at expansion — DST shifts keep a 09:00 standup at 09:00 local. Bare-UTC storage of recurring times is the classic calendar bug and is banned in core.</p>`,16)])])}const m=t(r,[["render",o]]);export{u as __pageData,m as default};
